package com.example.editor.metamodel.export;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import com.example.editor.metamodel.core.MetaAttribute;
import com.example.editor.metamodel.core.MetaClass;
import com.example.editor.metamodel.core.MetaModel;
import com.example.editor.metamodel.core.MetaPrimitiveType;
import com.example.editor.metamodel.core.MetaRelation;
import com.example.editor.metamodel.core.MetaRelationKind;
import com.example.editor.metamodel.core.MetaTypeReferenceKind;

import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;

/** Projects the neutral metamodel to static Blockly JSON block definitions. */
final class BlocklyMetamodelExportSupport {
    private final ObjectMapper objectMapper;
    /** Descripción: Inicializa una instancia de BlocklyMetamodelExportSupport con sus dependencias y datos de entrada. Entradas: objectMapper: componente de conversión utilizado durante el procesamiento. Salida: deja la instancia inicializada y lista para su uso. */ BlocklyMetamodelExportSupport(ObjectMapper objectMapper) { this.objectMapper = objectMapper; }

    /** Descripción: Ejecuta la operación «json» correspondiente a la responsabilidad de BlocklyMetamodelExportSupport. Entradas: context: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ String json(NeutralMetamodelExportContext context) {
        MetaModel model = context.neutralMetamodel();
        Map<String,Object> envelope = new LinkedHashMap<>();
        envelope.put("schemaVersion", "1.0"); envelope.put("kind", "HYDRA_BLOCKLY_LAYER"); envelope.put("layer", "METAMODEL"); envelope.put("metamodelId", model.id()); envelope.put("payload", Map.of("metamodel", model)); envelope.put("blockDefinitions", blockDefinitions(model)); envelope.put("annotations", Map.of("hydra.blockly.integration", "independent-layer", "hydra.blockly.execution", "declarative"));
        try { return objectMapper.writerWithDefaultPrettyPrinter().writeValueAsString(envelope); }
        catch(JacksonException exception) { throw new IllegalStateException("Could not serialize Blockly metamodel export", exception); }
    }

    /** Descripción: Ejecuta la operación «javascript» correspondiente a la responsabilidad de BlocklyMetamodelExportSupport. Entradas: context: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ String javascript(NeutralMetamodelExportContext context) {
        String json = json(context).replace("</", "<\\/");
        return "/* Generated by HYDRA: static Blockly definitions + independent metamodel layer. */\n(function(root){\n  'use strict';\n  const layer = " + json + ";\n  const bridge = root.HydraBlocklyBridge = root.HydraBlocklyBridge || { layers: {}, registerLayer: function(kind,value){ this.layers[kind]=value; } };\n  bridge.registerLayer(layer.layer, layer);\n  if (root.Blockly) {\n    const defineBlocks = root.Blockly.common && typeof root.Blockly.common.defineBlocksWithJsonArray === 'function' ? root.Blockly.common.defineBlocksWithJsonArray.bind(root.Blockly.common) : (typeof root.Blockly.defineBlocksWithJsonArray === 'function' ? root.Blockly.defineBlocksWithJsonArray.bind(root.Blockly) : null);\n    if (defineBlocks !== null) defineBlocks(layer.blockDefinitions);\n  }\n  if (typeof root.dispatchEvent === 'function' && typeof root.CustomEvent === 'function') root.dispatchEvent(new root.CustomEvent('hydra:blockly-layer', { detail: layer }));\n})(typeof globalThis !== 'undefined' ? globalThis : window);\n";
    }

    /** Descripción: Ejecuta la operación «blockDefinitions» correspondiente a la responsabilidad de BlocklyMetamodelExportSupport. Entradas: model: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private List<Map<String,Object>> blockDefinitions(MetaModel model) {
        List<Map<String,Object>> result = new ArrayList<>();
        for(MetaClass metaClass : model.classes()) {
            if("true".equals(metaClass.annotations().get("blockly:base"))) continue;
            Map<String,Object> block = new LinkedHashMap<>();
            String type = metaClass.annotations().getOrDefault("blockly:type", safe(metaClass.name()));
            block.put("type", type);
            List<Map<String,Object>> args = new ArrayList<>();
            List<String> messageParts = new ArrayList<>();
            for(MetaAttribute attribute : metaClass.attributes()) { Map<String,Object> arg = field(attribute); args.add(arg); messageParts.add(attribute.name() + " %" + args.size()); }
            for(MetaRelation relation : model.relations().stream().filter(item -> item.sourceTypeId().equals(metaClass.id()) && item.kind() != MetaRelationKind.INHERITANCE).toList()) { Map<String,Object> arg = input(relation, model); args.add(arg); messageParts.add(relation.name() + " %" + args.size()); }
            String preservedMessage = metaClass.annotations().getOrDefault("blockly:message0", "");
            block.put("message0", preservedMessage.isBlank() ? metaClass.name() + (messageParts.isEmpty() ? "" : " " + String.join(" ", messageParts)) : preservedMessage);
            if(!args.isEmpty()) block.put("args0", args);
            putPreserved(block, "output", metaClass.annotations().get("blockly:output")); putPreserved(block, "previousStatement", metaClass.annotations().get("blockly:previousStatement")); putPreserved(block, "nextStatement", metaClass.annotations().get("blockly:nextStatement"));
            if(!block.containsKey("output") && !block.containsKey("previousStatement") && !block.containsKey("nextStatement")) { block.put("previousStatement", null); block.put("nextStatement", null); }
            block.put("colour", 210); block.put("tooltip", "HYDRA " + metaClass.name());
            result.add(block);
        }
        return result;
    }

    /** Descripción: Ejecuta la operación «field» correspondiente a la responsabilidad de BlocklyMetamodelExportSupport. Entradas: attribute: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private Map<String,Object> field(MetaAttribute attribute) {
        Map<String,Object> result = new LinkedHashMap<>();
        String type = attribute.annotations().get("blockly:fieldType");
        if(type == null || type.isBlank()) type = isBoolean(attribute) ? "field_checkbox" : isNumeric(attribute) ? "field_number" : "field_input";
        result.put("type", type); result.put("name", safe(attribute.name()).toUpperCase());
        if(type.equals("field_checkbox")) result.put("checked", Boolean.parseBoolean(attribute.defaultValue())); else if(type.equals("field_number")) result.put("value", numeric(attribute.defaultValue())); else result.put("text", attribute.defaultValue().isBlank() ? attribute.name() : attribute.defaultValue());
        return result;
    }
    /** Descripción: Ejecuta la operación «input» correspondiente a la responsabilidad de BlocklyMetamodelExportSupport. Entradas: relation: dato de entrada necesario para la operación; model: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private Map<String,Object> input(MetaRelation relation, MetaModel model) { Map<String,Object> result = new LinkedHashMap<>(); result.put("type", relation.annotations().getOrDefault("blockly:inputType", "input_value")); result.put("name", safe(relation.name()).toUpperCase()); String preserved=relation.annotations().getOrDefault("blockly:check",""); if(!preserved.isBlank()) result.put("check", List.of(preserved.split(","))); else model.classes().stream().filter(item -> item.id().equals(relation.targetTypeId()) && !"true".equals(item.annotations().get("blockly:base"))).findFirst().ifPresent(target -> result.put("check", target.annotations().getOrDefault("blockly:type", safe(target.name())))); return result; }
    /** Descripción: Ejecuta la operación «putPreserved» correspondiente a la responsabilidad de BlocklyMetamodelExportSupport. Entradas: target: dato de entrada necesario para la operación; key: identificador que delimita el recurso objetivo; raw: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void putPreserved(Map<String,Object> target, String key, String raw) { if(raw == null || raw.isBlank()) return; try { target.put(key, objectMapper.readTree(raw)); } catch(JacksonException exception) { target.put(key, raw); } }
    /** Descripción: Evalúa la condición «isBoolean» sin modificar el estado externo. Entradas: attribute: dato de entrada necesario para la operación. Salida: devuelve un indicador que expresa el resultado de la condición. */ private boolean isBoolean(MetaAttribute attribute) { return attribute.type().kind() == MetaTypeReferenceKind.PRIMITIVE && MetaPrimitiveType.BOOLEAN.name().equals(attribute.type().targetId()); }
    /** Descripción: Evalúa la condición «isNumeric» sin modificar el estado externo. Entradas: attribute: dato de entrada necesario para la operación. Salida: devuelve un indicador que expresa el resultado de la condición. */ private boolean isNumeric(MetaAttribute attribute) { if(attribute.type().kind() != MetaTypeReferenceKind.PRIMITIVE) return false; return List.of("BYTE","SHORT","INTEGER","LONG","FLOAT","DOUBLE","DECIMAL","BIG_INTEGER").contains(attribute.type().targetId()); }
    /** Descripción: Ejecuta la operación «numeric» correspondiente a la responsabilidad de BlocklyMetamodelExportSupport. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private Object numeric(String value) { try { return Double.valueOf(value); } catch(Exception exception) { return 0; } }
    /** Descripción: Ejecuta la operación «safe» correspondiente a la responsabilidad de BlocklyMetamodelExportSupport. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private String safe(String value) { String result=value==null?"":value.trim().replaceAll("[^A-Za-z0-9_]+","_").replaceAll("^_+|_+$","").toLowerCase(); return result.isBlank()?"hydra_block":result; }
}
